css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; grid-template-columns: repeat(2, 1fr); gap: 8%; padding: 11%; border-radius: 9%; background: linear-gradient(#1e293b, #0b1220); box-shadow: inset 0 0 0 2px #334155; }
.loader span { position: relative; overflow: hidden; border-radius: 3px; background: rgba(255, 255, 255, .08); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .12); }
.loader span::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; background: linear-gradient(var(--accent-2), var(--accent)); animation: core-load calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader span:nth-child(1) { --peak: 92%; }
.loader span:nth-child(2) { --peak: 62%; }
.loader span:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(3) { --peak: 100%; }
.loader span:nth-child(3)::after { animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(4) { --peak: 46%; }
.loader span:nth-child(4)::after { animation-delay: calc(var(--loader-speed) * .9); }
@keyframes core-load { 0%, 100% { height: 16%; } 50% { height: var(--peak); } }
